#include "chemistry.hpp"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <numeric>
#include <set>

static std::vector<int> dense(const std::vector<std::vector<int>> &values) {
    std::vector<int> order(values.size()), ranks(values.size());
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](int a, int b) { return values[a] < values[b]; });
    int rank = 0, previous = -1;
    for (int i : order) {
        if (previous < 0 || values[i] != values[previous])
            ++rank;
        ranks[i] = rank;
        previous = i;
    }
    return ranks;
}
static int rankCount(const std::vector<int> &ranks) {
    return *std::max_element(ranks.begin(), ranks.end());
}
static std::vector<int> refine(const Molecule &m, std::vector<int> ranks) {
    for (;;) {
        std::vector<std::vector<int>> values(m.atoms.size());
        for (std::size_t a = 0; a < m.atoms.size(); ++a) {
            std::vector<std::pair<int, int>> neighbors;
            for (int e : m.adjacent[a])
                neighbors.emplace_back(ranks[m.bonds[e].other(static_cast<int>(a))],
                                       m.bonds[e].type);
            std::sort(neighbors.begin(), neighbors.end());
            values[a].push_back(ranks[a]);
            for (const auto &value : neighbors) {
                values[a].push_back(value.first);
                values[a].push_back(value.second);
            }
        }
        std::vector<int> next = dense(values);
        if (rankCount(next) == rankCount(ranks))
            return next;
        ranks = std::move(next);
    }
}
void canonicalRanks(Molecule &m, const Elements &elements) {
    std::vector<std::vector<int>> values;
    for (std::size_t i = 0; i < m.atoms.size(); ++i) {
        const Atom &a = m.atoms[i];
        values.push_back({static_cast<int>(m.adjacent[i].size()), elements.at(a.symbol).number,
                          a.mass, a.charge, a.hydrogens, a.aromatic ? 1 : 0});
    }
    std::vector<int> ranks = refine(m, dense(values));
    m.classes = rankCount(ranks);
    while (rankCount(ranks) < static_cast<int>(m.atoms.size())) {
        std::vector<int> counts(m.atoms.size() + 1);
        for (int rank : ranks)
            ++counts[rank];
        int smallest = 1;
        while (counts[smallest] < 2)
            ++smallest;
        int chosen =
            static_cast<int>(std::find(ranks.begin(), ranks.end(), smallest) - ranks.begin());
        values.clear();
        for (int i = 0; i < static_cast<int>(ranks.size()); ++i)
            values.push_back({2 * ranks[i] - (i == chosen ? 1 : 0)});
        ranks = refine(m, dense(values));
    }
    m.ranks = std::move(ranks);
}
static std::string atomNotation(const Molecule &m, int index, const Elements &elements) {
    const Atom &a = m.atoms[index];
    std::string symbol = a.symbol;
    if (a.aromatic)
        for (char &c : symbol)
            if (c >= 'A' && c <= 'Z')
                c = static_cast<char>(c - 'A' + 'a');
    static const std::set<std::string> organic = {"B", "C", "N",  "O",  "P",
                                                  "S", "F", "Cl", "Br", "I"},
                                       aromatic = {"B", "C", "N", "O", "P", "S"};
    std::optional<int> hydrogens = m.organicHydrogens(index, elements);
    if (organic.count(a.symbol) && (!a.aromatic || aromatic.count(a.symbol)) && a.mass == 0 &&
        a.charge == 0 &&
        (!a.aromatic || m.needsPi(index, elements, true) == m.needsPi(index, elements, false)) &&
        hydrogens && *hydrogens == a.hydrogens)
        return symbol;
    std::string out = "[";
    if (a.mass)
        out += std::to_string(a.mass);
    out += symbol;
    if (a.hydrogens) {
        out += 'H';
        if (a.hydrogens >= 2)
            out += std::to_string(a.hydrogens);
    }
    if (a.charge) {
        out += a.charge > 0 ? '+' : '-';
        if (std::abs(a.charge) >= 2)
            out += std::to_string(std::abs(a.charge));
    }
    return out + "]";
}
static std::string bondNotation(const Molecule &m, const Bond &bond) {
    bool inRing = m.atoms[bond.a].aromatic && m.atoms[bond.b].aromatic && bond.ring;
    if (bond.type == 1)
        return inRing ? "-" : "";
    if (bond.type == 2)
        return "=";
    if (bond.type == 3)
        return "#";
    return inRing ? "" : ":";
}
std::string canonicalSmiles(const Molecule &m, const Elements &elements) {
    int start = static_cast<int>(std::find(m.ranks.begin(), m.ranks.end(), 1) - m.ranks.begin());
    std::vector<bool> visited(m.atoms.size());
    std::vector<int> visitOrder(m.atoms.size()), classification(m.bonds.size());
    std::vector<std::vector<std::pair<int, int>>> children(m.atoms.size());
    int serial = 0;
    const std::function<void(int, int)> visit = [&](int a, int parent) {
        visited[a] = true;
        visitOrder[a] = ++serial;
        std::vector<int> neighbors = m.adjacent[a];
        std::sort(neighbors.begin(), neighbors.end(), [&](int x, int y) {
            return m.ranks[m.bonds[x].other(a)] < m.ranks[m.bonds[y].other(a)];
        });
        for (int e : neighbors) {
            if (e == parent || classification[e] == 2)
                continue;
            int b = m.bonds[e].other(a);
            if (!visited[b]) {
                classification[e] = 1;
                children[a].emplace_back(b, e);
                visit(b, e);
            } else
                classification[e] = 2;
        }
    };
    visit(start, -1);
    std::map<int, int> assignments;
    std::set<int> used;
    const auto numberText = [](int value) {
        if (value <= 9)
            return std::to_string(value);
        char buffer[16];
        std::snprintf(buffer, sizeof(buffer), "%%%02d", value);
        return std::string(buffer);
    };
    const std::function<std::string(int)> write = [&](int a) {
        std::string out = atomNotation(m, a, elements);
        std::vector<int> closures;
        for (int e : m.adjacent[a])
            if (classification[e] == 2)
                closures.push_back(e);
        std::sort(closures.begin(), closures.end(), [&](int x, int y) {
            return visitOrder[m.bonds[x].other(a)] < visitOrder[m.bonds[y].other(a)];
        });
        for (int e : closures) {
            auto found = assignments.find(e);
            if (found != assignments.end()) {
                out += numberText(found->second);
                used.erase(found->second);
                assignments.erase(found);
            } else {
                int number = 1;
                while (used.count(number))
                    ++number;
                assignments[e] = number;
                used.insert(number);
                out += bondNotation(m, m.bonds[e]) + numberText(number);
            }
        }
        for (std::size_t i = 0; i < children[a].size(); ++i) {
            const auto &child = children[a][i];
            std::string branch = bondNotation(m, m.bonds[child.second]) + write(child.first);
            out += i + 1 < children[a].size() ? "(" + branch + ")" : branch;
        }
        return out;
    };
    return write(start);
}

#ifndef CHEMISTRY_HPP
#define CHEMISTRY_HPP
#include <array>
#include <cstdint>
#include <bitset>
#include <map>
#include <optional>
#include <sstream>
#include <string>
#include <vector>
struct Element {
    std::string symbol;
    int number, weight;
    std::vector<int> valences;
};
using Elements = std::map<std::string, Element>;
struct Choice {
    std::string symbol;
    bool aromatic = false;
};
struct Atom {
    std::string symbol;
    bool aromatic = false, bracket = false;
    int mass = 0, charge = 0, hydrogens = 0, column = 0;
    std::vector<Choice> choices;
    char wildcard = 0;
};
struct Bond {
    int a, b;
    char symbol = 0;
    int type = 0, multiplicity = 0, match = 0;
    bool ring = false;
    int other(int) const;
};
struct Molecule {
    std::string name;
    std::vector<Atom> atoms;
    std::vector<Bond> bonds;
    std::vector<std::vector<int>> adjacent, rings;
    std::vector<bool> ringAtoms;
    std::vector<int> ranks;
    int classes = 0;
    std::string canonical, scaffold, formula, lipinski;
    int weight = 0, heavy = 0, rotatable = 0, donors = 0, acceptors = 0, charge = 0;
    std::bitset<1024> bits;
    int paths = 0;
    void build();
    const Bond *bond(int, int) const;
    int base(int) const;
    int multiplicity(int) const;
    bool needsPi(int, const Elements &, bool) const;
    std::optional<int> organicHydrogens(int, const Elements &) const;
};
struct ParseError {
    std::string reason;
    int column;
};
struct Parsed {
    std::optional<Molecule> molecule;
    std::optional<ParseError> error;
};
Elements readElements();
bool ignored(const std::string &);
std::vector<std::string> readLines(const std::string &);
std::vector<std::string> split(const std::string &, char);
std::string join(const std::vector<std::string> &, const std::string &);
bool digit(char);
std::optional<std::pair<Atom, std::size_t>> organic(const std::string &, std::size_t);
std::pair<Atom, std::string> bracket(const std::string &, const Elements &);
int symbolType(char);
Parsed parseSmiles(const std::string &, const Elements &, bool);
std::pair<Atom, std::string> patternAtom(const std::string &, std::size_t, std::size_t &);
Molecule moleculePattern(const Molecule &);
void detectRings(Molecule &);
std::optional<ParseError> kekulize(Molecule &, const Elements &);
void canonicalRanks(Molecule &, const Elements &);
std::string canonicalSmiles(const Molecule &, const Elements &);
struct Embeddings {
    int count = 0, unique = 0;
    std::vector<int> first;
};
Embeddings embeddings(const Molecule &, const Molecule &);
void fingerprint(Molecule &, const Elements &);
struct Fraction {
    int n, d;
    Fraction(int = 0, int = 1);
    int compare(Fraction) const;
    std::string text() const;
};
struct Similarity {
    Fraction value;
    int common, total;
};
Similarity similarity(const Molecule &, const Molecule &);
template <typename... Values> std::string text(const Values &...values) {
    std::ostringstream out;
    (out << ... << values);
    return out.str();
}
#endif

#include "chemistry.hpp"
#include <algorithm>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <numeric>
#include <set>
#include <stdexcept>

using Paragraph = std::vector<std::string>;
using Paragraphs = std::vector<Paragraph>;
static bool validName(const std::string &value) {
    return !value.empty() && value.size() <= 32 &&
           std::all_of(value.begin(), value.end(), [](char c) {
               return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' ||
                      c == '_' || c == '-';
           });
}
static std::optional<ParseError> analyze(Molecule &m, const Elements &elements) {
    detectRings(m);
    for (Bond &bond : m.bonds) {
        bond.type = symbolType(bond.symbol);
        if (!bond.type)
            bond.type = bond.ring && m.atoms[bond.a].aromatic && m.atoms[bond.b].aromatic ? 4 : 1;
    }
    if (auto failure = kekulize(m, elements))
        return failure;
    for (int i = 0; i < static_cast<int>(m.atoms.size()); ++i) {
        Atom &atom = m.atoms[i];
        if (atom.bracket) {
            if (m.multiplicity(i) + atom.hydrogens >
                elements.at(atom.symbol).valences.back() + std::abs(atom.charge))
                return ParseError{"bad valence", atom.column};
        } else {
            std::optional<int> h = m.organicHydrogens(i, elements);
            if (!h)
                return ParseError{"bad valence", atom.column};
            atom.hydrogens = *h;
        }
    }
    return std::nullopt;
}
static void properties(Molecule &m, const Elements &elements) {
    std::map<std::string, int> counts;
    int hydrogens = 0;
    std::vector<int> heavyDegree(m.atoms.size());
    std::vector<bool> triple(m.atoms.size());
    for (int i = 0; i < static_cast<int>(m.atoms.size()); ++i) {
        const Atom &atom = m.atoms[i];
        ++counts[atom.symbol];
        hydrogens += atom.hydrogens;
        m.charge += atom.charge;
        m.weight += atom.mass ? atom.mass * 1000 : elements.at(atom.symbol).weight;
        m.heavy += atom.symbol != "H";
        int attached = atom.hydrogens;
        for (int e : m.adjacent[i]) {
            const Bond &bond = m.bonds[e];
            if (m.atoms[bond.other(i)].symbol == "H")
                ++attached;
            else
                ++heavyDegree[i];
            if (bond.multiplicity == 3)
                triple[i] = true;
        }
        if (atom.symbol == "N" || atom.symbol == "O") {
            ++m.acceptors;
            if (attached)
                ++m.donors;
        }
    }
    counts["H"] += hydrogens;
    m.weight += hydrogens * elements.at("H").weight;
    std::vector<std::string> order;
    if (counts["C"] > 0) {
        order.push_back("C");
        if (counts["H"] > 0)
            order.push_back("H");
    }
    for (const auto &entry : counts)
        if (entry.second > 0 && (counts["C"] == 0 || (entry.first != "C" && entry.first != "H")))
            order.push_back(entry.first);
    for (const std::string &symbol : order) {
        m.formula += symbol;
        if (counts[symbol] > 1)
            m.formula += std::to_string(counts[symbol]);
    }
    for (const Bond &bond : m.bonds)
        if (bond.multiplicity == 1 && !bond.ring && heavyDegree[bond.a] >= 2 &&
            heavyDegree[bond.b] >= 2 && !triple[bond.a] && !triple[bond.b])
            ++m.rotatable;
    int violations = (m.weight > 500000) + (m.donors > 5) + (m.acceptors > 10);
    m.lipinski = violations < 2 ? "pass" : "fail";
}
static std::string scaffold(const Molecule &m, const Elements &elements) {
    if (m.rings.empty())
        return "";
    std::vector<bool> remaining(m.atoms.size(), true);
    for (;;) {
        int remove = -1;
        for (int a = 0; a < static_cast<int>(m.atoms.size()); ++a) {
            if (!remaining[a] || m.ringAtoms[a])
                continue;
            int degree = 0;
            for (int e : m.adjacent[a])
                degree += remaining[m.bonds[e].other(a)];
            if (degree == 1) {
                remove = a;
                break;
            }
        }
        if (remove < 0)
            break;
        remaining[remove] = false;
    }
    std::vector<bool> keep = remaining;
    for (const Bond &bond : m.bonds)
        if (bond.multiplicity == 2) {
            if (remaining[bond.a])
                keep[bond.b] = true;
            if (remaining[bond.b])
                keep[bond.a] = true;
        }
    Molecule result;
    std::vector<int> renumber(m.atoms.size(), -1);
    for (int a = 0; a < static_cast<int>(m.atoms.size()); ++a)
        if (keep[a]) {
            Atom atom = m.atoms[a];
            for (int e : m.adjacent[a])
                if (!keep[m.bonds[e].other(a)])
                    atom.hydrogens += m.bonds[e].multiplicity;
            renumber[a] = static_cast<int>(result.atoms.size());
            result.atoms.push_back(std::move(atom));
        }
    for (const Bond &bond : m.bonds)
        if (keep[bond.a] && keep[bond.b]) {
            Bond copy = bond;
            copy.a = renumber[bond.a];
            copy.b = renumber[bond.b];
            result.bonds.push_back(copy);
        }
    result.build();
    canonicalRanks(result, elements);
    return canonicalSmiles(result, elements);
}
static std::string ringRelation(const Molecule &m, const std::vector<int> &a,
                                const std::vector<int> &b) {
    std::vector<int> common;
    for (int atom : a)
        if (std::find(b.begin(), b.end(), atom) != b.end())
            common.push_back(atom);
    if (common.size() == 1)
        return "spiro";
    if (common.size() == 2 && m.bond(common[0], common[1]))
        return "fused";
    return common.size() >= 2 ? "bridged" : "";
}
struct RingSystem {
    std::vector<int> rings;
    std::string kind;
    int atoms;
};
static std::vector<RingSystem> ringSystems(const Molecule &m) {
    std::vector<std::vector<int>> adjacency(m.rings.size());
    for (int i = 0; i < static_cast<int>(m.rings.size()); ++i)
        for (int j = i + 1; j < static_cast<int>(m.rings.size()); ++j)
            if (!ringRelation(m, m.rings[i], m.rings[j]).empty()) {
                adjacency[i].push_back(j);
                adjacency[j].push_back(i);
            }
    std::vector<bool> seen(m.rings.size());
    std::vector<RingSystem> result;
    for (int first = 0; first < static_cast<int>(m.rings.size()); ++first) {
        if (seen[first])
            continue;
        std::vector<int> queue = {first};
        seen[first] = true;
        for (std::size_t h = 0; h < queue.size(); ++h)
            for (int next : adjacency[queue[h]])
                if (!seen[next]) {
                    seen[next] = true;
                    queue.push_back(next);
                }
        std::sort(queue.begin(), queue.end());
        std::set<int> atoms;
        std::string kind = queue.size() == 1 ? "isolated" : "spiro";
        for (std::size_t i = 0; i < queue.size(); ++i) {
            atoms.insert(m.rings[queue[i]].begin(), m.rings[queue[i]].end());
            for (std::size_t j = i + 1; j < queue.size(); ++j) {
                std::string relation = ringRelation(m, m.rings[queue[i]], m.rings[queue[j]]);
                if (relation == "bridged")
                    kind = "bridged";
                else if (relation == "fused" && kind != "bridged")
                    kind = "fused";
            }
        }
        result.push_back({queue, kind, static_cast<int>(atoms.size())});
    }
    return result;
}
static bool ringAromatic(const Molecule &m, const std::vector<int> &ring) {
    for (int atom : ring)
        if (!m.atoms[atom].aromatic)
            return false;
    return true;
}
static std::string integers(const std::vector<int> &values, const std::string &separator,
                            int offset = 0) {
    std::vector<std::string> parts;
    for (int value : values)
        parts.push_back(std::to_string(value + offset));
    return join(parts, separator);
}
static std::string memberNames(const std::vector<Molecule> &molecules,
                               const std::vector<int> &indices) {
    std::vector<std::string> names;
    for (int i : indices)
        names.push_back(molecules[i].name);
    return join(names, ",");
}
static Paragraphs canonicalParagraphs(const std::vector<Molecule> &molecules) {
    std::map<std::string, std::vector<int>> canonGroups, formulaGroups, scaffoldGroups;
    std::vector<std::string> canonOrder, formulaOrder;
    int acyclic = 0;
    for (int i = 0; i < static_cast<int>(molecules.size()); ++i) {
        const Molecule &m = molecules[i];
        if (!canonGroups.count(m.canonical))
            canonOrder.push_back(m.canonical);
        canonGroups[m.canonical].push_back(i);
        if (!formulaGroups.count(m.formula))
            formulaOrder.push_back(m.formula);
        formulaGroups[m.formula].push_back(i);
        if (m.scaffold.empty())
            ++acyclic;
        else
            scaffoldGroups[m.scaffold].push_back(i);
    }
    Paragraph canonical = {
        text("CANONICAL molecules=", molecules.size(), " unique=", canonGroups.size())};
    for (const Molecule &m : molecules)
        canonical.push_back(text(m.name, " ", m.canonical, " classes=", m.classes,
                                 " charge=", m.charge > 0 ? "+" : "", m.charge));
    Paragraph duplicates, isomers;
    int duplicateCount = 0, duplicateMolecules = 0, isomerCount = 0;
    for (const std::string &key : canonOrder) {
        const std::vector<int> &indices = canonGroups.at(key);
        if (indices.size() < 2)
            continue;
        ++duplicateCount;
        duplicateMolecules += static_cast<int>(indices.size());
        duplicates.push_back(
            text("group ", duplicateCount, " ", key, " members=", memberNames(molecules, indices)));
    }
    duplicates.insert(duplicates.begin(), text("DUPLICATES groups=", duplicateCount,
                                               " molecules=", duplicateMolecules));
    for (const std::string &formula : formulaOrder) {
        const std::vector<int> &indices = formulaGroups.at(formula);
        std::set<std::string> forms;
        for (int i : indices)
            forms.insert(molecules[i].canonical);
        if (forms.size() < 2)
            continue;
        isomers.push_back(text("isomer ", ++isomerCount, " ", formula, " forms=", forms.size(),
                               " members=", memberNames(molecules, indices)));
    }
    isomers.insert(isomers.begin(), text("ISOMERS groups=", isomerCount));
    Paragraph scaffolds = {
        text("SCAFFOLDS distinct=", scaffoldGroups.size(), " acyclic=", acyclic)};
    std::vector<std::string> keys;
    for (const auto &entry : scaffoldGroups)
        keys.push_back(entry.first);
    std::sort(keys.begin(), keys.end(), [&](const std::string &a, const std::string &b) {
        return scaffoldGroups.at(a).size() != scaffoldGroups.at(b).size()
                   ? scaffoldGroups.at(a).size() > scaffoldGroups.at(b).size()
                   : a < b;
    });
    for (std::size_t i = 0; i < keys.size(); ++i)
        scaffolds.push_back(text("scaffold ", i + 1, " ", keys[i],
                                 " count=", scaffoldGroups.at(keys[i]).size(),
                                 " members=", memberNames(molecules, scaffoldGroups.at(keys[i]))));
    return {canonical, duplicates, isomers, scaffolds};
}
static Paragraphs ringParagraphs(const std::vector<Molecule> &molecules) {
    Paragraphs result;
    int cyclic = 0, total = 0, aromatic = 0;
    std::map<int, int> sizes;
    std::map<std::string, int> kinds;
    for (const Molecule &m : molecules) {
        if (m.rings.empty())
            continue;
        ++cyclic;
        total += static_cast<int>(m.rings.size());
        std::vector<RingSystem> systems = ringSystems(m);
        int aromaticCount = 0, ringBonds = 0,
            ringAtoms = static_cast<int>(std::count(m.ringAtoms.begin(), m.ringAtoms.end(), true));
        for (const Bond &bond : m.bonds)
            ringBonds += bond.ring;
        for (const std::vector<int> &ring : m.rings) {
            ++sizes[static_cast<int>(ring.size())];
            aromaticCount += ringAromatic(m, ring);
        }
        aromatic += aromaticCount;
        Paragraph paragraph = {text("MOLECULE ", m.name, " atoms=", m.atoms.size(),
                                    " bonds=", m.bonds.size(), " rings=", m.rings.size(),
                                    " aromatic=", aromaticCount, " systems=", systems.size(),
                                    " ring_atoms=", ringAtoms, " ring_bonds=", ringBonds)};
        for (std::size_t i = 0; i < m.rings.size(); ++i) {
            int hetero = 0;
            for (int atom : m.rings[i])
                hetero += m.atoms[atom].symbol != "C";
            paragraph.push_back(text("ring ", i + 1, " size=", m.rings[i].size(),
                                     " aromatic=", ringAromatic(m, m.rings[i]) ? "yes" : "no",
                                     " hetero=", hetero, " atoms=", integers(m.rings[i], "-", 1)));
        }
        for (std::size_t i = 0; i < systems.size(); ++i) {
            const RingSystem &s = systems[i];
            ++kinds[s.kind];
            paragraph.push_back(text("system ", i + 1, " kind=", s.kind,
                                     " rings=", integers(s.rings, ",", 1), " atoms=", s.atoms));
        }
        std::vector<std::string> doubleBonds;
        for (const Bond &bond : m.bonds)
            if (bond.type == 4 && bond.multiplicity == 2)
                doubleBonds.push_back(text(bond.a + 1, "=", bond.b + 1));
        paragraph.push_back("kekule " + (doubleBonds.empty() ? "-" : join(doubleBonds, " ")));
        result.push_back(std::move(paragraph));
    }
    std::string sizeLine = "sizes";
    for (const auto &entry : sizes)
        sizeLine += text(" ", entry.first, "=", entry.second);
    if (sizes.empty())
        sizeLine += " -";
    result.push_back({text("SUMMARY molecules=", molecules.size(), " cyclic=", cyclic,
                           " rings=", total, " aromatic=", aromatic),
                      sizeLine,
                      text("systems isolated=", kinds["isolated"], " fused=", kinds["fused"],
                           " spiro=", kinds["spiro"], " bridged=", kinds["bridged"])});
    return result;
}
struct Query {
    std::string kind, id;
    std::vector<std::string> arguments;
    Molecule pattern;
    Fraction threshold;
    int count = 0;
};
static bool number(const std::string &value, int low, int high) {
    if (value.empty() || value.size() > 2 || (value.size() > 1 && value[0] == '0') ||
        !std::all_of(value.begin(), value.end(), digit))
        return false;
    int n = std::stoi(value);
    return n >= low && n <= high;
}
static std::optional<Fraction> threshold(const std::string &value) {
    std::vector<std::string> a = split(value, '/');
    if (a.size() != 2 || !number(a[0], 0, 99) || !number(a[1], 1, 99))
        return std::nullopt;
    int n = std::stoi(a[0]), d = std::stoi(a[1]);
    return n <= d ? std::optional<Fraction>(Fraction(n, d)) : std::nullopt;
}
static std::pair<std::optional<Query>, std::string>
checkQuery(const std::vector<std::string> &tokens, std::set<std::string> &seen,
           const std::map<std::string, int> &byName, const Elements &elements) {
    static const std::set<std::string> kinds = {"MATCH",  "CONTAINS", "MATRIX", "NEAREST",
                                                "WITHIN", "COMPARE",  "CLUSTER"};
    const std::string &kind = tokens[0];
    if (!kinds.count(kind))
        return {std::nullopt, "unknown query"};
    if (tokens.size() == 1 || !validName(tokens[1]))
        return {std::nullopt, "bad id"};
    const std::string &id = tokens[1];
    if (!seen.insert(id).second)
        return {std::nullopt, "duplicate id"};
    std::vector<std::string> args(tokens.begin() + 2, tokens.end());
    bool length = kind == "MATCH" || kind == "CLUSTER" ? args.size() == 1
                  : kind == "MATRIX"                   ? args.size() >= 2 && args.size() <= 12
                                                       : args.size() == 2;
    if (!length)
        return {std::nullopt, "bad arguments"};
    Query q;
    q.kind = kind;
    q.id = id;
    q.arguments = args;
    if (kind == "MATCH") {
        Parsed parsed = parseSmiles(args[0], elements, true);
        if (parsed.error)
            return {std::nullopt, text("bad pattern ", parsed.error->reason, " at column ",
                                       parsed.error->column)};
        q.pattern = std::move(*parsed.molecule);
    } else if (kind == "CLUSTER") {
        std::optional<Fraction> value = threshold(args[0]);
        if (!value)
            return {std::nullopt, "bad threshold"};
        q.threshold = *value;
    } else if (kind == "CONTAINS" || kind == "MATRIX" || kind == "COMPARE") {
        for (const std::string &name : args)
            if (!byName.count(name))
                return {std::nullopt, "unknown molecule " + name};
        std::set<std::string> names(args.begin(), args.end());
        if (names.size() != args.size())
            return {std::nullopt, "repeated molecule"};
    } else {
        if (!byName.count(args[0]))
            return {std::nullopt, "unknown molecule " + args[0]};
        if (kind == "NEAREST") {
            if (!number(args[1], 1, 99))
                return {std::nullopt, "bad count"};
            q.count = std::stoi(args[1]);
        } else {
            std::optional<Fraction> value = threshold(args[1]);
            if (!value)
                return {std::nullopt, "bad threshold"};
            q.threshold = *value;
        }
    }
    return {std::move(q), ""};
}
static Paragraphs substructureParagraphs(const std::vector<Query> &queries,
                                         const std::vector<Molecule> &molecules,
                                         const std::map<std::string, int> &byName) {
    Paragraphs paragraphs;
    int patterns = 0, hits = 0, contains = 0, found = 0;
    for (const Query &q : queries) {
        if (q.kind == "MATCH") {
            ++patterns;
            Paragraph hitLines;
            int total = 0, topCount = 0;
            std::string top;
            for (const Molecule &m : molecules) {
                Embeddings result = embeddings(q.pattern, m);
                if (!result.count)
                    continue;
                ++hits;
                total += result.count;
                hitLines.push_back(text(m.name, " count=", result.count, " unique=", result.unique,
                                        " map=", integers(result.first, ",")));
                if (result.count > topCount) {
                    top = m.name;
                    topCount = result.count;
                }
            }
            Paragraph paragraph = {text("MATCH ", q.id, " ", q.arguments[0], " atoms=",
                                        q.pattern.atoms.size(), " bonds=", q.pattern.bonds.size(),
                                        " hits=", hitLines.size(), " embeddings=", total)};
            paragraph.insert(paragraph.end(), hitLines.begin(), hitLines.end());
            if (!top.empty())
                paragraph.push_back(text("top ", top, " count=", topCount));
            paragraphs.push_back(std::move(paragraph));
        } else if (q.kind == "CONTAINS") {
            ++contains;
            const Molecule &x = molecules[byName.at(q.arguments[0])],
                           &y = molecules[byName.at(q.arguments[1])];
            Embeddings result = embeddings(moleculePattern(x), y);
            std::string value = text("CONTAINS ", q.id, " ", x.name, " ", y.name, " result=");
            if (result.count) {
                ++found;
                value += text("yes count=", result.count, " unique=", result.unique,
                              " map=", integers(result.first, ","));
            } else
                value += "no";
            paragraphs.push_back({value});
        }
    }
    paragraphs.push_back({text("SUMMARY patterns=", patterns, " hits=", hits,
                               " contains=", contains, " found=", found)});
    return paragraphs;
}
static Paragraphs similarityParagraphs(const std::vector<Query> &queries,
                                       const std::vector<Molecule> &molecules,
                                       const std::map<std::string, int> &byName) {
    int n = static_cast<int>(molecules.size());
    std::vector<std::vector<Similarity>> matrix(n, std::vector<Similarity>(n));
    for (int i = 0; i < n; ++i)
        for (int j = i; j < n; ++j)
            matrix[i][j] = matrix[j][i] = similarity(molecules[i], molecules[j]);
    Paragraph fingerprints = {text("FINGERPRINTS molecules=", n, " size=1024 depth=5")};
    for (const Molecule &m : molecules)
        fingerprints.push_back(text(m.name, " bits=", m.bits.count(), " paths=", m.paths));
    Paragraphs output = {fingerprints};
    for (const Query &q : queries) {
        const std::vector<std::string> &args = q.arguments;
        Paragraph paragraph;
        if (q.kind == "MATRIX") {
            std::vector<int> indices;
            for (const std::string &name : args)
                indices.push_back(byName.at(name));
            paragraph.push_back(text("MATRIX ", q.id, " size=", args.size()));
            int bestI = 0, bestJ = 1;
            for (int i = 0; i < static_cast<int>(indices.size()); ++i) {
                std::vector<std::string> values;
                for (int j = 0; j < static_cast<int>(indices.size()); ++j) {
                    values.push_back(matrix[indices[i]][indices[j]].value.text());
                    if (i < j && matrix[indices[i]][indices[j]].value.compare(
                                     matrix[indices[bestI]][indices[bestJ]].value) > 0) {
                        bestI = i;
                        bestJ = j;
                    }
                }
                paragraph.push_back("row " + args[i] + " " + join(values, " "));
            }
            paragraph.push_back(text("best ", args[bestI], " ", args[bestJ], " ",
                                     matrix[indices[bestI]][indices[bestJ]].value.text()));
        } else if (q.kind == "NEAREST" || q.kind == "WITHIN") {
            int base = byName.at(args[0]);
            std::vector<int> order;
            for (int i = 0; i < n; ++i)
                if (i != base)
                    order.push_back(i);
            std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
                return matrix[base][a].value.compare(matrix[base][b].value) > 0;
            });
            if (q.kind == "NEAREST") {
                if (order.size() > static_cast<std::size_t>(q.count))
                    order.resize(q.count);
                paragraph.push_back(text("NEAREST ", q.id, " ", args[0], " count=", order.size()));
            } else {
                order.erase(std::remove_if(order.begin(), order.end(),
                                           [&](int i) {
                                               return matrix[base][i].value.compare(q.threshold) <
                                                      0;
                                           }),
                            order.end());
                paragraph.push_back(text("WITHIN ", q.id, " ", args[0], " threshold=",
                                         q.threshold.text(), " count=", order.size()));
            }
            for (std::size_t i = 0; i < order.size(); ++i) {
                const Similarity &value = matrix[base][order[i]];
                paragraph.push_back(text(i + 1, " ", molecules[order[i]].name, " ",
                                         value.value.text(), " common=", value.common));
            }
        } else if (q.kind == "COMPARE") {
            int a = byName.at(args[0]), b = byName.at(args[1]);
            const Similarity &value = matrix[a][b];
            paragraph.push_back(text(
                "COMPARE ", q.id, " ", args[0], " ", args[1], " bits=", molecules[a].bits.count(),
                ",", molecules[b].bits.count(), " common=", value.common, " union=", value.total,
                " tanimoto=", value.value.text(),
                " identical=", molecules[a].canonical == molecules[b].canonical ? "yes" : "no"));
        } else if (q.kind == "CLUSTER") {
            std::vector<std::vector<int>> neighbors(n);
            std::vector<int> order(n);
            std::iota(order.begin(), order.end(), 0);
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    if (i != j && matrix[i][j].value.compare(q.threshold) >= 0)
                        neighbors[i].push_back(j);
            std::stable_sort(order.begin(), order.end(), [&](int a, int b) {
                return neighbors[a].size() > neighbors[b].size();
            });
            std::vector<bool> assigned(n);
            std::vector<std::vector<int>> clusters;
            int singletons = 0;
            for (int center : order) {
                if (assigned[center])
                    continue;
                std::vector<int> members = {center};
                assigned[center] = true;
                for (int neighbor : neighbors[center])
                    if (!assigned[neighbor]) {
                        members.push_back(neighbor);
                        assigned[neighbor] = true;
                    }
                singletons += members.size() == 1;
                clusters.push_back(std::move(members));
            }
            paragraph.push_back(text("CLUSTER ", q.id, " threshold=", q.threshold.text(),
                                     " clusters=", clusters.size(), " singletons=", singletons));
            int number = 0;
            for (const std::vector<int> &members : clusters)
                if (members.size() > 1)
                    paragraph.push_back(text(
                        "cluster ", ++number, " centroid=", molecules[members.front()].name,
                        " size=", members.size(), " members=", memberNames(molecules, members)));
        }
        if (!paragraph.empty())
            output.push_back(std::move(paragraph));
    }
    return output;
}
static void writeLines(const std::string &name, const Paragraph &lines) {
    std::ofstream file("output/" + name);
    if (!file)
        throw std::runtime_error("cannot write " + name);
    for (const std::string &line : lines)
        file << line << '\n';
}
static void writeParagraphs(const std::string &name, const Paragraphs &paragraphs) {
    Paragraph output;
    for (const Paragraph &paragraph : paragraphs)
        if (!paragraph.empty()) {
            if (!output.empty())
                output.push_back("");
            output.insert(output.end(), paragraph.begin(), paragraph.end());
        }
    writeLines(name, output);
}
int main() {
    Elements elements = readElements();
    std::vector<Molecule> molecules;
    std::map<std::string, int> byName, causes;
    std::set<std::string> seenNames;
    Paragraph moleculeErrors, queryErrors;
    int moleculeLines = 0, queryLines = 0;
    std::vector<std::string> source = readLines("input/molecules.smi");
    for (std::size_t i = 0; i < source.size(); ++i) {
        if (ignored(source[i]))
            continue;
        ++moleculeLines;
        std::vector<std::string> tokens = split(source[i], ' ');
        if (tokens.size() != 2 || tokens[0].empty() || !validName(tokens[1])) {
            moleculeErrors.push_back(text("line ", i + 1, ": bad line"));
            ++causes["bad line"];
            continue;
        }
        const std::string &name = tokens[1];
        if (!seenNames.insert(name).second) {
            moleculeErrors.push_back(text("line ", i + 1, " ", name, ": duplicate name"));
            ++causes["duplicate name"];
            continue;
        }
        Parsed parsed = parseSmiles(tokens[0], elements, false);
        if (!parsed.error)
            parsed.error = analyze(*parsed.molecule, elements);
        if (parsed.error) {
            moleculeErrors.push_back(text("line ", i + 1, " ", name, ": ", parsed.error->reason,
                                          " at column ", parsed.error->column));
            ++causes[parsed.error->reason];
            continue;
        }
        Molecule molecule = std::move(*parsed.molecule);
        molecule.name = name;
        properties(molecule, elements);
        canonicalRanks(molecule, elements);
        molecule.canonical = canonicalSmiles(molecule, elements);
        molecule.scaffold = scaffold(molecule, elements);
        fingerprint(molecule, elements);
        byName[name] = static_cast<int>(molecules.size());
        molecules.push_back(std::move(molecule));
    }
    std::vector<Query> queries;
    std::set<std::string> seenIds;
    source = readLines("input/queries.txt");
    for (std::size_t i = 0; i < source.size(); ++i) {
        if (ignored(source[i]))
            continue;
        ++queryLines;
        std::vector<std::string> tokens = split(source[i], ' ');
        auto checked = checkQuery(tokens, seenIds, byName, elements);
        if (!checked.second.empty()) {
            const std::string &reason = checked.second;
            std::string error = text("line ", i + 1);
            if (reason == "unknown query")
                error += ": unknown query";
            else if (reason == "bad id")
                error += " " + tokens[0] + ": bad id";
            else
                error += " " + tokens[0] + " " + tokens[1] + ": " + reason;
            queryErrors.push_back(error);
            std::string cause = reason;
            if (cause.compare(0, 12, "bad pattern ") == 0)
                cause = "bad pattern";
            if (cause.compare(0, 17, "unknown molecule ") == 0)
                cause = "unknown molecule";
            ++causes[cause];
        } else
            queries.push_back(std::move(*checked.first));
    }
    Paragraph propertiesLines = {
        "name,formula,weight,heavy_atoms,rings,rotatable,donors,acceptors,lipinski"};
    for (const Molecule &m : molecules) {
        std::ostringstream row;
        row << m.name << ',' << m.formula << ',' << m.weight / 1000 << '.' << std::setw(3)
            << std::setfill('0') << m.weight % 1000 << ',' << m.heavy << ',' << m.rings.size()
            << ',' << m.rotatable << ',' << m.donors << ',' << m.acceptors << ',' << m.lipinski;
        propertiesLines.push_back(row.str());
    }
    moleculeErrors.insert(moleculeErrors.begin(),
                          text("MOLECULES lines=", moleculeLines, " valid=", molecules.size(),
                               " errors=", moleculeErrors.size()));
    queryErrors.insert(queryErrors.begin(), text("QUERIES lines=", queryLines, " valid=",
                                                 queries.size(), " errors=", queryErrors.size()));
    std::vector<std::string> names;
    for (const auto &entry : causes)
        names.push_back(entry.first);
    std::sort(names.begin(), names.end(), [&](const std::string &a, const std::string &b) {
        return causes[a] != causes[b] ? causes[a] > causes[b] : a < b;
    });
    Paragraph causeLines = {text("CAUSES kinds=", causes.size())};
    for (const std::string &name : names)
        causeLines.push_back(text(name, "=", causes[name]));
    std::filesystem::create_directories("output");
    writeLines("properties.csv", propertiesLines);
    writeParagraphs("canonical.txt", canonicalParagraphs(molecules));
    writeParagraphs("rings.txt", ringParagraphs(molecules));
    writeParagraphs("substructure.txt", substructureParagraphs(queries, molecules, byName));
    writeParagraphs("similarity.txt", similarityParagraphs(queries, molecules, byName));
    writeParagraphs("errors.txt", {moleculeErrors, queryErrors, causeLines});
}

#include "chemistry.hpp"
#include <algorithm>
#include <fstream>
#include <stdexcept>
int Bond::other(int atom) const { return atom == a ? b : a; }
void Molecule::build() {
    std::sort(bonds.begin(), bonds.end(),
              [](const Bond &x, const Bond &y) { return x.a != y.a ? x.a < y.a : x.b < y.b; });
    adjacent.assign(atoms.size(), {});
    for (int i = 0; i < static_cast<int>(bonds.size()); ++i) {
        adjacent[bonds[i].a].push_back(i);
        adjacent[bonds[i].b].push_back(i);
    }
    for (int a = 0; a < static_cast<int>(atoms.size()); ++a)
        std::sort(adjacent[a].begin(), adjacent[a].end(),
                  [&](int x, int y) { return bonds[x].other(a) < bonds[y].other(a); });
}
const Bond *Molecule::bond(int a, int b) const {
    for (int index : adjacent[a])
        if (bonds[index].other(a) == b)
            return &bonds[index];
    return nullptr;
}
int Molecule::base(int a) const {
    int sum = 0;
    for (int index : adjacent[a])
        sum += bonds[index].type == 4 ? 1 : bonds[index].type;
    return sum;
}
int Molecule::multiplicity(int a) const {
    int sum = 0;
    for (int index : adjacent[a])
        sum += bonds[index].multiplicity;
    return sum;
}
bool Molecule::needsPi(int a, const Elements &elements, bool hydrogens) const {
    return atoms[a].aromatic && elements.at(atoms[a].symbol).valences.front() + atoms[a].charge >=
                                    base(a) + (hydrogens ? atoms[a].hydrogens : 0) + 1;
}
std::optional<int> Molecule::organicHydrogens(int a, const Elements &elements) const {
    int total = multiplicity(a);
    for (int valence : elements.at(atoms[a].symbol).valences)
        if (valence >= total)
            return valence - total;
    return std::nullopt;
}
bool ignored(const std::string &line) { return line.empty() || line[0] == '#'; }
std::vector<std::string> readLines(const std::string &name) {
    std::ifstream file(name);
    if (!file)
        throw std::runtime_error("cannot read " + name);
    std::vector<std::string> result;
    std::string value;
    while (std::getline(file, value))
        result.push_back(value);
    return result;
}
std::vector<std::string> split(const std::string &value, char separator) {
    std::vector<std::string> result;
    std::size_t start = 0;
    for (;;) {
        std::size_t end = value.find(separator, start);
        result.push_back(value.substr(start, end == std::string::npos ? end : end - start));
        if (end == std::string::npos)
            return result;
        start = end + 1;
    }
}
std::string join(const std::vector<std::string> &parts, const std::string &separator) {
    std::string result;
    for (std::size_t i = 0; i < parts.size(); ++i) {
        if (i)
            result += separator;
        result += parts[i];
    }
    return result;
}
Elements readElements() {
    Elements elements;
    for (const std::string &line : readLines("input/elements.txt")) {
        if (ignored(line))
            continue;
        std::vector<std::string> a = split(line, ' ');
        Element e{a[0], std::stoi(a[1]), std::stoi(a[2]), {}};
        for (const std::string &v : split(a[3], ','))
            e.valences.push_back(std::stoi(v));
        elements.emplace(e.symbol, std::move(e));
    }
    return elements;
}

#include "chemistry.hpp"
#include <algorithm>
#include <functional>
#include <set>
static std::vector<int> canonicalRing(const std::vector<int> &ring) {
    std::size_t first =
        static_cast<std::size_t>(std::min_element(ring.begin(), ring.end()) - ring.begin());
    int n = static_cast<int>(ring.size()),
        direction = ring[(first + 1) % ring.size()] < ring[(first + ring.size() - 1) % ring.size()]
                        ? 1
                        : -1;
    std::vector<int> result;
    for (int i = 0; i < n; ++i)
        result.push_back(ring[(static_cast<int>(first) + direction * i + n) % n]);
    return result;
}
void detectRings(Molecule &m) {
    struct Candidate {
        std::vector<int> atoms;
        std::bitset<300> bonds;
    };
    int n = static_cast<int>(m.atoms.size());
    std::vector<Candidate> candidates;
    std::set<std::string> seen;
    std::map<std::pair<int, int>, int> bondIndex;
    for (int i = 0; i < static_cast<int>(m.bonds.size()); ++i)
        bondIndex[{m.bonds[i].a, m.bonds[i].b}] = i;
    for (int root = 0; root < n; ++root) {
        std::vector<int> parent(n, -2), queue = {root};
        parent[root] = -1;
        for (std::size_t h = 0; h < queue.size(); ++h)
            for (int e : m.adjacent[queue[h]]) {
                int next = m.bonds[e].other(queue[h]);
                if (parent[next] == -2) {
                    parent[next] = queue[h];
                    queue.push_back(next);
                }
            }
        const auto path = [&](int a) {
            std::vector<int> result;
            for (; a >= 0; a = parent[a])
                result.push_back(a);
            return result;
        };
        for (const Bond &bond : m.bonds) {
            if (parent[bond.a] == bond.b || parent[bond.b] == bond.a)
                continue;
            std::vector<int> px = path(bond.a), py = path(bond.b);
            std::set<int> atoms(px.begin(), px.end() - 1);
            bool overlap = false;
            for (auto a = py.begin(); a != py.end() - 1; ++a)
                overlap = overlap || atoms.count(*a) != 0;
            if (overlap)
                continue;
            std::reverse(px.begin(), px.end());
            px.insert(px.end(), py.begin(), py.end() - 1);
            std::bitset<300> vector;
            for (std::size_t i = 0; i < px.size(); ++i) {
                int a = px[i], b = px[(i + 1) % px.size()];
                vector.set(bondIndex.at({std::min(a, b), std::max(a, b)}));
            }
            if (seen.insert(vector.to_string()).second)
                candidates.push_back({std::move(px), vector});
        }
    }
    std::stable_sort(
        candidates.begin(), candidates.end(),
        [](const Candidate &a, const Candidate &b) { return a.atoms.size() < b.atoms.size(); });
    std::array<std::optional<std::bitset<300>>, 300> basis;
    m.ringAtoms.assign(m.atoms.size(), false);
    for (const Candidate &candidate : candidates) {
        std::bitset<300> reduced = candidate.bonds;
        while (reduced.any()) {
            int pivot = static_cast<int>(m.bonds.size()) - 1;
            while (!reduced[pivot])
                --pivot;
            if (basis[pivot])
                reduced ^= *basis[pivot];
            else {
                basis[pivot] = reduced;
                m.rings.push_back(canonicalRing(candidate.atoms));
                for (int atom : candidate.atoms)
                    m.ringAtoms[atom] = true;
                for (std::size_t i = 0; i < m.bonds.size(); ++i)
                    if (candidate.bonds[i])
                        m.bonds[i].ring = true;
                break;
            }
        }
    }
    std::sort(m.rings.begin(), m.rings.end(),
              [](const std::vector<int> &a, const std::vector<int> &b) {
                  return a.size() != b.size() ? a.size() < b.size() : a < b;
              });
}
std::optional<ParseError> kekulize(Molecule &m, const Elements &elements) {
    int n = static_cast<int>(m.atoms.size());
    std::vector<bool> need(n), seen(n);
    std::vector<int> paired(n, -1);
    for (int i = 0; i < n; ++i)
        need[i] = m.needsPi(i, elements, true);
    for (int first = 0; first < n; ++first) {
        if (!need[first] || seen[first])
            continue;
        std::vector<int> system = {first};
        seen[first] = true;
        for (std::size_t h = 0; h < system.size(); ++h)
            for (int e : m.adjacent[system[h]]) {
                const Bond &bond = m.bonds[e];
                int next = bond.other(system[h]);
                if (bond.type == 4 && need[next] && !seen[next]) {
                    seen[next] = true;
                    system.push_back(next);
                }
            }
        std::sort(system.begin(), system.end());
        std::vector<bool> member(n);
        for (int atom : system)
            member[atom] = true;
        const std::function<bool()> match = [&]() {
            int u = -1;
            for (int atom : system)
                if (paired[atom] < 0) {
                    u = atom;
                    break;
                }
            if (u < 0)
                return true;
            for (int e : m.adjacent[u]) {
                const Bond &bond = m.bonds[e];
                int v = bond.other(u);
                if (bond.type != 4 || !member[v] || paired[v] >= 0)
                    continue;
                paired[u] = v;
                paired[v] = u;
                if (match())
                    return true;
                paired[u] = paired[v] = -1;
            }
            return false;
        };
        if (!match())
            return ParseError{"kekulization failed", m.atoms[first].column};
    }
    for (Bond &bond : m.bonds)
        bond.multiplicity = bond.type == 4 ? (paired[bond.a] == bond.b ? 2 : 1) : bond.type;
    return std::nullopt;
}

#include "chemistry.hpp"
#include <algorithm>
#include <functional>
#include <numeric>
#include <set>

std::pair<Atom, std::string> patternAtom(const std::string &source, std::size_t at,
                                         std::size_t &next) {
    Atom atom;
    char c = source[at];
    if (c == '*' || c == 'A' || c == 'a') {
        atom.wildcard = c;
        next = at + 1;
        return {atom, ""};
    }
    if (c == '[') {
        std::size_t end = source.find(']', at + 1);
        if (end == std::string::npos)
            return {atom, "unclosed bracket"};
        for (const std::string &part : split(source.substr(at + 1, end - at - 1), ',')) {
            if (part.empty())
                return {atom, "bad bracket atom"};
            auto parsed = organic(part, 0);
            if (!parsed || parsed->second != part.size())
                return {atom, "bad bracket atom"};
            atom.choices.push_back({parsed->first.symbol, parsed->first.aromatic});
        }
        next = end + 1;
        return {atom, ""};
    }
    auto parsed = organic(source, at);
    if (!parsed)
        return {atom, "unexpected character"};
    atom = std::move(parsed->first);
    atom.choices.push_back({atom.symbol, atom.aromatic});
    next = parsed->second;
    return {atom, ""};
}
static bool atomMatches(const Atom &pattern, const Atom &atom) {
    if (pattern.wildcard == '*')
        return true;
    if (pattern.wildcard == 'A')
        return !atom.aromatic;
    if (pattern.wildcard == 'a')
        return atom.aromatic;
    for (const Choice &choice : pattern.choices)
        if (choice.symbol == atom.symbol && choice.aromatic == atom.aromatic)
            return true;
    return false;
}
Molecule moleculePattern(const Molecule &m) {
    Molecule pattern;
    for (const Atom &atom : m.atoms) {
        Atom a;
        a.choices.push_back({atom.symbol, atom.aromatic});
        pattern.atoms.push_back(std::move(a));
    }
    for (const Bond &bond : m.bonds) {
        Bond b{bond.a, bond.b};
        b.match = 1 << bond.type;
        pattern.bonds.push_back(b);
    }
    pattern.build();
    return pattern;
}
Embeddings embeddings(const Molecule &pattern, const Molecule &molecule) {
    Embeddings result;
    if (pattern.atoms.size() > molecule.atoms.size())
        return result;
    std::vector<int> mapping(pattern.atoms.size(), -1);
    std::vector<bool> used(molecule.atoms.size());
    std::set<std::array<std::uint64_t, 2>> sets;
    const std::function<void(int)> search = [&](int index) {
        if (index == static_cast<int>(pattern.atoms.size())) {
            ++result.count;
            if (result.first.empty())
                for (int atom : mapping)
                    result.first.push_back(atom + 1);
            std::array<std::uint64_t, 2> mask{};
            for (int atom : mapping)
                mask[atom / 64] |= std::uint64_t{1} << (atom % 64);
            sets.insert(mask);
            return;
        }
        for (int candidate = 0; candidate < static_cast<int>(molecule.atoms.size()); ++candidate) {
            if (used[candidate] || !atomMatches(pattern.atoms[index], molecule.atoms[candidate]))
                continue;
            bool valid = true;
            for (int e : pattern.adjacent[index]) {
                const Bond &bond = pattern.bonds[e];
                int other = bond.other(index);
                if (other >= index)
                    continue;
                const Bond *actual = molecule.bond(candidate, mapping[other]);
                if (!actual || !(bond.match & (1 << actual->type))) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                mapping[index] = candidate;
                used[candidate] = true;
                search(index + 1);
                used[candidate] = false;
                mapping[index] = -1;
            }
        }
    };
    search(0);
    result.unique = static_cast<int>(sets.size());
    return result;
}
void fingerprint(Molecule &m, const Elements &elements) {
    std::vector<int> codes;
    for (std::size_t i = 0; i < m.atoms.size(); ++i)
        codes.push_back(16 * elements.at(m.atoms[i].symbol).number + (m.atoms[i].aromatic ? 8 : 0) +
                        static_cast<int>(m.adjacent[i].size()));
    std::vector<bool> visited(m.atoms.size());
    const std::function<void(int, int, int)> visit = [&](int atom, int depth, int hash) {
        ++m.paths;
        m.bits.set(hash % 1024);
        if (depth == 5)
            return;
        for (int e : m.adjacent[atom]) {
            const Bond &bond = m.bonds[e];
            int next = bond.other(atom);
            if (visited[next])
                continue;
            int value = (hash * 31 + bond.type) % 1000003;
            value = (value * 31 + codes[next]) % 1000003;
            visited[next] = true;
            visit(next, depth + 1, value);
            visited[next] = false;
        }
    };
    for (int i = 0; i < static_cast<int>(m.atoms.size()); ++i) {
        visited[i] = true;
        visit(i, 0, codes[i]);
        visited[i] = false;
    }
}
Fraction::Fraction(int numerator, int denominator) {
    int divisor = std::gcd(numerator, denominator);
    n = numerator / divisor;
    d = denominator / divisor;
}
int Fraction::compare(Fraction value) const {
    int left = n * value.d, right = value.n * d;
    return (left > right) - (left < right);
}
std::string Fraction::text() const { return std::to_string(n) + "/" + std::to_string(d); }
Similarity similarity(const Molecule &a, const Molecule &b) {
    int common = static_cast<int>((a.bits & b.bits).count()),
        total = static_cast<int>((a.bits | b.bits).count());
    return {Fraction(common, total), common, total};
}

#include "chemistry.hpp"
#include <algorithm>
#include <set>
bool digit(char c) { return c >= '0' && c <= '9'; }
std::optional<std::pair<Atom, std::size_t>> organic(const std::string &source, std::size_t at) {
    Atom atom;
    if (at + 1 < source.size() && (source.substr(at, 2) == "Cl" || source.substr(at, 2) == "Br")) {
        atom.symbol = source.substr(at, 2);
        return std::make_pair(atom, at + 2);
    }
    char c = source[at];
    if (std::string("BCNOPSFI").find(c) != std::string::npos) {
        atom.symbol = std::string(1, c);
        return std::make_pair(atom, at + 1);
    }
    if (std::string("bcnops").find(c) != std::string::npos) {
        atom.symbol = std::string(1, static_cast<char>(c - 'a' + 'A'));
        atom.aromatic = true;
        return std::make_pair(atom, at + 1);
    }
    return std::nullopt;
}
std::pair<Atom, std::string> bracket(const std::string &content, const Elements &elements) {
    Atom atom;
    atom.bracket = true;
    std::size_t i = 0;
    while (i < content.size() && digit(content[i]))
        ++i;
    if (i >= 4 || (i && content[0] == '0'))
        return {atom, "bad bracket atom"};
    if (i)
        atom.mass = std::stoi(content.substr(0, i));
    if (i == content.size())
        return {atom, "bad bracket atom"};
    char c = content[i];
    if (std::string("bcnops").find(c) != std::string::npos) {
        atom.symbol = std::string(1, static_cast<char>(c - 'a' + 'A'));
        atom.aromatic = true;
        ++i;
    } else if (c >= 'A' && c <= 'Z') {
        if (i + 1 < content.size() && content[i + 1] >= 'a' && content[i + 1] <= 'z' &&
            elements.count(content.substr(i, 2))) {
            atom.symbol = content.substr(i, 2);
            i += 2;
        } else {
            atom.symbol = std::string(1, c);
            if (!elements.count(atom.symbol))
                return {atom, "unknown element"};
            ++i;
        }
    } else
        return {atom, "bad bracket atom"};
    if (content.substr(i, 2) == "@@")
        i += 2;
    else if (i < content.size() && content[i] == '@')
        ++i;
    if (i < content.size() && content[i] == 'H') {
        atom.hydrogens = 1;
        ++i;
        if (i < content.size() && digit(content[i]))
            atom.hydrogens = content[i++] - '0';
    }
    if (i < content.size() && (content[i] == '+' || content[i] == '-')) {
        int sign = content[i++] == '+' ? 1 : -1, magnitude = 1;
        if (i < content.size() && content[i] >= '1' && content[i] <= '9')
            magnitude = content[i++] - '0';
        atom.charge = sign * magnitude;
    }
    return {atom, i == content.size() ? "" : "bad bracket atom"};
}
int symbolType(char c) {
    if (c == '-' || c == '/' || c == '\\')
        return 1;
    if (c == '=')
        return 2;
    if (c == '#')
        return 3;
    if (c == ':')
        return 4;
    if (c == '~')
        return 5;
    return 0;
}
Parsed parseSmiles(const std::string &source, const Elements &elements, bool pattern) {
    Molecule m;
    int current = -1, pendingColumn = 0;
    char pending = 0;
    std::vector<std::pair<int, int>> stack;
    struct Open {
        int atom, column;
        char symbol;
    };
    std::map<int, Open> open;
    std::set<std::pair<int, int>> existing;
    const auto fail = [](const std::string &reason, int column) {
        return Parsed{std::nullopt, ParseError{reason, column}};
    };
    const auto addBond = [&](int a, int b, char symbol) {
        if (a > b)
            std::swap(a, b);
        Bond bond{a, b, symbol};
        if (pattern) {
            int kind = symbolType(symbol);
            bond.match = kind == 0   ? (1 << 1) | (1 << 4)
                         : kind == 5 ? (1 << 1) | (1 << 2) | (1 << 3) | (1 << 4)
                                     : 1 << kind;
        }
        m.bonds.push_back(bond);
        existing.insert({a, b});
    };
    for (std::size_t i = 0; i < source.size();) {
        char c = source[i];
        int column = static_cast<int>(i) + 1;
        const std::string symbols = pattern ? "-=#:~" : "-/\\=#:";
        if (symbols.find(c) != std::string::npos) {
            if (current < 0 || pending)
                return fail("misplaced bond", column);
            pending = c;
            pendingColumn = column;
            ++i;
        } else if (c == '(') {
            if (current < 0 || pending || (i && source[i - 1] == '('))
                return fail("misplaced branch", column);
            stack.emplace_back(current, column);
            ++i;
        } else if (c == ')') {
            if (stack.empty())
                return fail("unmatched parenthesis", column);
            if (pending)
                return fail("dangling bond", pendingColumn);
            if (i && source[i - 1] == '(')
                return fail("empty branch", column);
            current = stack.back().first;
            stack.pop_back();
            ++i;
        } else if (digit(c) || c == '%') {
            if (current < 0)
                return fail("misplaced ring closure", column);
            int number;
            if (c == '%') {
                if (i + 2 >= source.size() || !digit(source[i + 1]) || !digit(source[i + 2]))
                    return fail("bad ring number", column);
                number = 10 * (source[i + 1] - '0') + source[i + 2] - '0';
                i += 3;
            } else {
                number = c - '0';
                ++i;
            }
            char symbol = pending;
            pending = 0;
            auto found = open.find(number);
            if (found == open.end())
                open[number] = {current, column, symbol};
            else {
                Open old = found->second;
                if (old.atom == current)
                    return fail("self bond", column);
                if (old.symbol && symbol &&
                    (pattern ? old.symbol != symbol : symbolType(old.symbol) != symbolType(symbol)))
                    return fail("ring bond mismatch", column);
                std::pair<int, int> key = {std::min(old.atom, current),
                                           std::max(old.atom, current)};
                if (existing.count(key))
                    return fail("duplicate bond", column);
                addBond(old.atom, current, symbol ? symbol : old.symbol);
                open.erase(found);
            }
        } else {
            Atom atom;
            std::size_t next = i;
            std::string reason;
            if (pattern) {
                auto parsed = patternAtom(source, i, next);
                atom = std::move(parsed.first);
                reason = std::move(parsed.second);
            } else if (c == '[') {
                std::size_t end = source.find(']', i + 1);
                if (end == std::string::npos)
                    return fail("unclosed bracket", column);
                auto parsed = bracket(source.substr(i + 1, end - i - 1), elements);
                atom = std::move(parsed.first);
                reason = std::move(parsed.second);
                next = end + 1;
            } else {
                auto parsed = organic(source, i);
                if (!parsed)
                    reason = "unexpected character";
                else {
                    atom = std::move(parsed->first);
                    next = parsed->second;
                }
            }
            if (!reason.empty())
                return fail(reason, column);
            atom.column = column;
            m.atoms.push_back(std::move(atom));
            int index = static_cast<int>(m.atoms.size()) - 1;
            if (current >= 0)
                addBond(current, index, pending);
            current = index;
            pending = 0;
            i = next;
        }
    }
    if (pending)
        return fail("dangling bond", pendingColumn);
    if (!stack.empty())
        return fail("unmatched parenthesis", stack.front().second);
    if (!open.empty()) {
        int column = static_cast<int>(source.size()) + 1;
        for (const auto &entry : open)
            column = std::min(column, entry.second.column);
        return fail("unclosed ring", column);
    }
    m.build();
    return {std::move(m), std::nullopt};
}
